<script setup lang="ts">
import { computed, ref } from 'vue'
import { analyze, bitBytes, bom, byteCount, cpLabel, graphemes, hexBytes, normalizeNewlines, type EncodingName } from './encoding'
import { decodeRepresentations, toHtmlDecimal, toHtmlHex, toJsEscapes, toUnicodeCodePoints } from './converter'
import { compareRtf, inspectRtf, type RtfStats } from './rtf'
import RtfTreeView from './RtfTreeView.vue'
const text=ref('Hello 😀 世界\nSelect some text to inspect it.'); const inputOpen=ref(true); const active=ref('Bytes'); const findOpen=ref(false); const query=ref(''); const caseSensitive=ref(false); const wholeWord=ref(false); const matchIndex=ref(0); const inputEl=ref<HTMLTextAreaElement|null>(null); const includeBom=ref(false); const alloc=ref(4096); const sel=ref({start:0,end:0}); const pinned=ref('😀'); const hovered=ref('')
const openedFile=ref(''); const openedBytes=ref(0); const rtfEditedRaw=ref(''); const inspectedRun=ref<number|null>(null); const treeSelection=ref<{start:number;end:number}|null>(null); const rtfStats=ref<RtfStats|null>(null); const rtfOriginal=ref<RtfStats|null>(null); const rtfEdited=ref<RtfStats|null>(null); const rtfOriginalName=ref(''); const rtfEditedName=ref(''); const rtfCompare=computed(()=>rtfOriginal.value&&rtfEdited.value?compareRtf(rtfOriginal.value,rtfEdited.value):null); const convertInput=ref('😀 & 世界'); const convertMode=ref('Unicode code points');
const converted=computed(()=>convertMode.value==='Unicode code points'?toUnicodeCodePoints(convertInput.value):convertMode.value==='JavaScript escapes'?toJsEscapes(convertInput.value):convertMode.value==='HTML decimal'?toHtmlDecimal(convertInput.value):convertMode.value==='HTML hexadecimal'?toHtmlHex(convertInput.value):hexBytes(convertInput.value,'UTF-8'))
const fileEncoding=ref<EncodingName>('UTF-8'); const newlineStyle=ref<'Preserve'|'LF'|'CRLF'|'CR'>('Preserve')
const selected=computed(()=>text.value.slice(sel.value.start,sel.value.end)); const total=computed(()=>analyze(text.value)); const ss=computed(()=>analyze(selected.value));
const selectionPercent=computed(()=>total.value.sizes['UTF-8'].bytes.length ? ss.value.sizes['UTF-8'].bytes.length/total.value.sizes['UTF-8'].bytes.length*100 : 0)
const matches=computed(()=>{if(!query.value)return [] as {start:number,end:number}[]; const hay=caseSensitive.value?text.value:text.value.toLocaleLowerCase(); const needle=caseSensitive.value?query.value:query.value.toLocaleLowerCase(); const out:{start:number,end:number}[]=[]; let from=0; while(needle && (from=hay.indexOf(needle,from))!==-1){const before=from===0?' ':hay[from-1], after=from+needle.length>=hay.length?' ':hay[from+needle.length]; const ok=!wholeWord.value || (!/[\\p{L}\\p{N}_]/u.test(before) && !/[\\p{L}\\p{N}_]/u.test(after)); if(ok)out.push({start:from,end:from+needle.length}); from+=Math.max(needle.length,1)} return out})
function gotoMatch(delta=0){if(!matches.value.length)return; matchIndex.value=(matchIndex.value+delta+matches.value.length)%matches.value.length; const m=matches.value[matchIndex.value]; requestAnimationFrame(()=>{inputEl.value?.focus(); inputEl.value?.setSelectionRange(m.start,m.end); sel.value=m})}
const size=(s:string,e:EncodingName)=>byteCount(s,e); const hex=(s:string,e:EncodingName='UTF-8')=>hexBytes(s,e); const bin=(s:string,e:EncodingName='UTF-8')=>bitBytes(s,e)
const fileText=computed(()=>normalizeNewlines(text.value,newlineStyle.value)); const payload=computed(()=>size(fileText.value,fileEncoding.value)); const bomSize=computed(()=>includeBom.value?bom(fileEncoding.value).length:0); const modeled=computed(()=>payload.value+bomSize.value); const allocation=computed(()=>modeled.value?Math.ceil(modeled.value/alloc.value)*alloc.value:0)
function selection(e:Event){const t=e.target as HTMLTextAreaElement; sel.value={start:t.selectionStart,end:t.selectionEnd}; if(t.selectionStart!==t.selectionEnd) active.value='Highlight'}
async function openFile(e:Event){const input=e.target as HTMLInputElement; const file=input.files?.[0]; if(!file)return; const bytes=new Uint8Array(await file.arrayBuffer()); const raw=new TextDecoder('utf-8',{fatal:false}).decode(bytes); openedFile.value=file.name; openedBytes.value=bytes.length; if(file.name.toLowerCase().endsWith('.rtf')||raw.startsWith('{\\rtf')){rtfStats.value=inspectRtf(raw,bytes.length); text.value=rtfStats.value.plainText; active.value='RTF'}else{rtfStats.value=null; text.value=raw; active.value='Bytes'} input.value=''}
async function loadRtfSide(e:Event,side:'original'|'edited'){const input=e.target as HTMLInputElement; const file=input.files?.[0]; if(!file)return; const bytes=new Uint8Array(await file.arrayBuffer()); const raw=new TextDecoder('utf-8',{fatal:false}).decode(bytes); const stats=inspectRtf(raw,bytes.length); if(side==='edited')rtfEditedRaw.value=raw; if(side==='original'){rtfOriginal.value=stats;rtfOriginalName.value=file.name}else{rtfEdited.value=stats;rtfEditedName.value=file.name} active.value='RTF'; input.value=''}
function signed(n:number){return n>0?'+'+n:String(n)}
function fontName(s:RtfStats,n:number|null){return n===null?'':s.fonts.find(f=>f.index===n)?.name||`font #${n}`}
function colorName(s:RtfStats,n:number|null){if(n===null)return '';const c=s.colors.find(x=>x.index===n);return c?`RGB(${c.red}, ${c.green}, ${c.blue})`:`color #${n}`}
type SourceToken={text:string;start:number;end:number;kind:'plain'|'mapped'|'control';run:number|null}
const sourceTokens=computed<SourceToken[]>(()=>{const raw=rtfEditedRaw.value,m=rtfEdited.value?.model;if(!raw||!m)return [];const boundaries=new Set<number>([0,raw.length]);m.runs.forEach(r=>{boundaries.add(r.sourceStart);boundaries.add(r.sourceEnd);r.sourceTokens.forEach(t=>{boundaries.add(t.start);boundaries.add(t.end)})});const points=[...boundaries].sort((a,b)=>a-b),out:SourceToken[]=[];for(let i=0;i<points.length-1;i++){const start=points[i],end=points[i+1];if(start===end)continue;const ri=m.runs.findIndex(r=>start<r.sourceEnd&&end>r.sourceStart),control=m.runs.some(r=>r.sourceTokens.some(t=>t.type!=='text'&&start<t.end&&end>t.start));out.push({text:raw.slice(start,end),start,end,kind:control?'control':ri>=0?'mapped':'plain',run:ri>=0?ri:null})}return out})
function inspectSourceToken(token:SourceToken){treeSelection.value={start:token.start,end:token.end};if(token.run!==null)inspectedRun.value=token.run}
function inspectRun(i:number){const legacy=rtfEdited.value?.runs[i],model=rtfEdited.value?.model;if(!legacy||!model)return;const semantic=model.runs.findIndex(r=>legacy.start<r.end&&legacy.end>r.start);inspectedRun.value=semantic>=0?semantic:null;treeSelection.value={start:legacy.sourceStart,end:legacy.sourceEnd}}
function inspectRange(start:number,end:number){treeSelection.value={start,end}}
function inspectTree(start:number,end:number){treeSelection.value={start,end};const i=rtfEdited.value?.model.runs.findIndex(r=>start<r.sourceEnd&&end>r.sourceStart)??-1;if(i>=0)inspectedRun.value=i}
function sourceBytes(run:{sourceStart:number;sourceEnd:number}){return new TextEncoder().encode(rtfEditedRaw.value.slice(run.sourceStart,run.sourceEnd)).length}
function decodeIntoInput(){convertInput.value=decodeRepresentations(convertInput.value)}
function csvCell(v:string){return `"${v.replaceAll('"','""')}"`}
function save(kind:'md'|'csv'){const a=total.value; const u8=a.sizes['UTF-8'].bytes.length; let body=''; if(kind==='md') body=`# Byte & Bit Reader Report\n\n## Message Summary\n\n- Graphemes: ${a.graphemes}\n- Code points: ${a.codepoints}\n- UTF-16 code units: ${a.utf16Units}\n- UTF-8: ${u8} bytes / ${u8*8} bits\n- UTF-16: ${a.sizes['UTF-16 LE'].bytes.length} bytes / ${a.sizes['UTF-16 LE'].bytes.length*8} bits\n- UTF-32: ${a.sizes['UTF-32 LE'].bytes.length} bytes / ${a.sizes['UTF-32 LE'].bytes.length*8} bits\n\n## File / BOM Analysis\n\n- Encoding: ${fileEncoding.value}\n- Newlines: ${newlineStyle.value}\n- Payload: ${payload.value} bytes\n- BOM: ${bomSize.value} bytes\n- Modeled file size: ${modeled.value} bytes\n\n## Original Message\n\n${text.value}\n`; else body=`section,item,value,bytes,bits\nsummary,UTF-8,,${u8},${u8*8}\nsummary,UTF-16 LE,,${a.sizes['UTF-16 LE'].bytes.length},${a.sizes['UTF-16 LE'].bytes.length*8}\nsummary,UTF-32 LE,,${a.sizes['UTF-32 LE'].bytes.length},${a.sizes['UTF-32 LE'].bytes.length*8}\nfile,${fileEncoding.value},payload,${payload.value},${payload.value*8}\nfile,BOM,,${bomSize.value},${bomSize.value*8}\nsource,original_message,${csvCell(text.value)},,\n`; const link=document.createElement('a'); link.href=URL.createObjectURL(new Blob([body],{type:kind==='csv'?'text/csv':'text/markdown'})); link.download=`byte-bit-report.${kind}`; link.click(); URL.revokeObjectURL(link.href)}
type TutorialLesson={title:string;summary:string;source:string;steps:string[]}
const tutorialOpen=ref(false),tutorialStep=ref(0),tutorialToast=ref('')
let tutorialToastTimer:number|undefined
const tutorialLessons:TutorialLesson[]=[
 {title:'Rendered text vs. RTF source',summary:'See why an RTF file contains much more than the words shown by an editor.',source:'{\\\\rtf1 Hello \\\\b world\\\\b0.}',steps:['RTF is plain source containing text plus control words and groups.','The word world can render bold even though the source also contains \\\\b and \\\\b0.','The inspector keeps rendered text and source ranges connected so you can move between them.']},
 {title:'Groups create scope',summary:'Learn how braces limit where formatting applies.',source:'{\\\\rtf1 Normal {\\\\b Bold} Normal again}',steps:['Curly braces create an RTF group.','The \\\\b control applies inside the nested group.','When the group closes, the parent formatting state is restored. This is why a \\\\b0 is not always required.']},
 {title:'Control words change state',summary:'Read common formatting controls such as bold, italic, font and size.',source:'{\\\\rtf1\\\\f2\\\\fs28\\\\b Example}',steps:['A control word begins with a backslash.','\\\\f2 selects font-table entry 2; \\\\fs28 means 28 half-points, or 14 pt; \\\\b enables bold.','Advanced Byte Reader records the exact source range that caused each computed property.']},
 {title:'Applied vs. computed',summary:'Follow formatting history instead of seeing only the final value.',source:'{\\\\rtf1\\\\b before {\\\\b0 off} after}',steps:['Applied shows the controls and scope changes that affected a property.','Computed shows the effective value at the selected text.','The history can show applied, override, reset and restored events, each linked back to source.']},
 {title:'Paragraph geometry',summary:'See how RTF stores indents and spacing as paragraph state.',source:'{\\\\rtf1\\\\pard\\\\li720\\\\fi-360\\\\sb120\\\\sa240 Paragraph}',steps:['\\\\li720 sets the left indent and \\\\fi-360 creates a hanging first-line offset.','\\\\sb and \\\\sa control space before and after the paragraph.','Advanced Byte Reader keeps the original twip values so the inspector stays faithful to the RTF source.']},
 {title:'Stylesheet inheritance',summary:'Follow named styles back through the RTF stylesheet.',source:'{\\\\rtf1{\\\\stylesheet{\\\\s0 Normal;}{\\\\s1\\\\sbasedon0\\\\b\\\\fs32 Heading 1;}}\\\\s1 Heading}',steps:['\\\\s1 applies paragraph style 1 rather than spelling every property out beside the text.','\\\\sbasedon0 means style 1 inherits from paragraph style 0.','The inspector exposes the ancestry and stylesheet source separately from direct formatting; the computed cascade will be applied in the next semantic pass.']},
 {title:'Lists and numbering',summary:'Trace a list paragraph through its override, definition and level.',source:`{\\\\rtf1{\\\\*\\\\listtable{\\\\list\\\\listtemplateid10{\\\\listlevel\\\\levelnfc0\\\\levelstartat1{\\\\leveltext \\\\'02\\\\'00.;}}\\\\listid42}}{\\\\*\\\\listoverridetable{\\\\listoverride\\\\listid42\\\\listoverridecount0\\\\ls3}}\\\\pard\\\\ls3\\\\ilvl0 Item}`,steps:['\\\\ls3 says which list override the paragraph uses; \\\\ilvl0 selects level 0.','The override points to list ID 42, whose level describes the numbering format and starting value.','The inspector lets you jump through paragraph → override → list → level instead of treating the visible marker as unexplained text.']}
]
const currentTutorial=computed(()=>tutorialLessons[tutorialStep.value])
function tutorialMove(delta:number){tutorialStep.value=Math.max(0,Math.min(tutorialLessons.length-1,tutorialStep.value+delta))}
function tutorialUseExample(){const raw=currentTutorial.value.source.replaceAll('\\\\','\\');rtfEditedRaw.value=raw;rtfEdited.value=inspectRtf(raw,new TextEncoder().encode(raw).length);rtfEditedName.value='Tutorial example';inspectedRun.value=null;treeSelection.value=null;active.value='RTF'}
function describeUi(message:string){tutorialToast.value=message;if(tutorialToastTimer)window.clearTimeout(tutorialToastTimer);tutorialToastTimer=window.setTimeout(()=>tutorialToast.value='',2400)}
const tabs=['Bytes','Highlight','Character','File / BOM','RTF','Converter','Bits']; const encodings:EncodingName[]=['UTF-8','UTF-16 LE','UTF-16 BE','UTF-32 LE','UTF-32 BE','ASCII','Latin-1']
</script>
<template>
<div class="page"><main class="app-card">
<header><div class="brand"><span class="logo">01</span><div><b>ADVANCED BYTE READER</b><small>File-format, Unicode & storage laboratory</small></div></div><nav><label class="open-file" title="Open text or RTF file">↥ <span>Open</span><input type="file" @change="openFile" accept=".txt,.md,.csv,.json,.xml,.html,.htm,.css,.js,.ts,.vue,.cpp,.c,.h,.hpp,.java,.kt,.py,.yaml,.yml,.rtf,text/*"></label><button @click="findOpen=!findOpen" title="Find">⌕ <span>Find</span></button><button @click="save('csv')" title="Export CSV">⇩ <span>CSV</span></button><button @click="save('md')" title="Export Markdown">⇩ <span>MD</span></button><button @click="tutorialOpen=true" title="Open the guided RTF tutorial" aria-label="Learn RTF with the guided tutorial" @contextmenu.prevent="describeUi('Learn opens short interactive lessons that explain RTF using the real inspector.')">? <span>Learn</span></button><button title="Settings">⚙</button></nav></header>
<div v-if="findOpen" class="findbar"><b>Find</b><input v-model="query" @input="matchIndex=0" @keydown.enter.prevent="gotoMatch($event.shiftKey?-1:1)" placeholder="Find text…"><span>{{matches.length ? matchIndex+1 : 0}} / {{matches.length}}</span><button @click="gotoMatch(-1)" title="Previous">‹</button><button @click="gotoMatch(1)" title="Next">›</button><label><input type="checkbox" v-model="caseSensitive"> Aa</label><label><input type="checkbox" v-model="wholeWord"> Whole</label><button @click="findOpen=false">×</button></div>
<div v-if="tutorialToast" class="ui-toast" role="status">{{tutorialToast}}</div><section v-if="tutorialOpen" class="tutorial"><div class="tutorial-head"><div><small>LEARN RTF · {{tutorialStep+1}} / {{tutorialLessons.length}}</small><h2>{{currentTutorial.title}}</h2><p>{{currentTutorial.summary}}</p></div><button @click="tutorialOpen=false" title="Close the tutorial" aria-label="Close tutorial">×</button></div><pre>{{currentTutorial.source.replaceAll('\\\\','\\')}}</pre><ol><li v-for="step in currentTutorial.steps">{{step}}</li></ol><div class="tutorial-actions"><button @click="tutorialMove(-1)" :disabled="tutorialStep===0" title="Go to the previous tutorial lesson">Previous</button><button class="try-example" @click="tutorialUseExample" title="Load this lesson's RTF into the real inspector" @contextmenu.prevent="describeUi('Try in inspector loads this tutorial example into the RTF parser so you can explore its source, tree and computed formatting.')">Try in inspector</button><button @click="tutorialMove(1)" :disabled="tutorialStep===tutorialLessons.length-1" title="Go to the next tutorial lesson">Next</button></div></section><section class="input-card"><div class="section-head" @click="inputOpen=!inputOpen"><div><b>{{inputOpen?'▾':'▸'}} INPUT</b><span>Paste or type any text</span></div><div class="summary"><b>{{total.sizes['UTF-8'].bytes.length}} B</b><span>{{total.sizes['UTF-8'].bytes.length*8}} bits</span></div></div><div v-show="inputOpen" class="input-wrap"><textarea ref="inputEl" v-model="text" @select="selection" @keyup="selection" @mouseup="selection" spellcheck="false"></textarea><div class="status"><span>{{total.graphemes}} graphemes</span><span>{{total.codepoints}} code points</span><span>{{total.utf16Units}} UTF-16 units</span><span>UTF-8 {{total.sizes['UTF-8'].bytes.length}} B</span></div></div></section>
<section class="workspace"><div class="tabs"><button v-for="t in tabs" :class="{active:active===t}" @click="active=t">{{t}}</button></div>
<div class="panel" v-if="active==='Bytes'"><div class="hero-grid"><article><small>MESSAGE SIZE · UTF-8</small><strong>{{total.sizes['UTF-8'].bytes.length}} bytes</strong><b>{{total.sizes['UTF-8'].bytes.length*8}} bits</b></article><article><small>LARGEST UTF-8 CHARACTER</small><strong class="char">{{total.largest}}</strong><b>{{size(total.largest,'UTF-8')}} bytes · {{size(total.largest,'UTF-8')*8}} bits</b></article></div><h3>Encoding comparison</h3><div class="rows"><div v-for="e in encodings"><b>{{e}}</b><span v-if="total.sizes[e].valid">{{total.sizes[e].bytes.length}} bytes</span><span v-else>Not representable ({{total.sizes[e].unrepresentable}})</span><span v-if="total.sizes[e].valid">{{total.sizes[e].bytes.length*8}} bits</span></div></div></div>
<div class="panel" v-else-if="active==='Highlight'"><div v-if="selected" class="selection"><small>HIGHLIGHTED SELECTION</small><blockquote>{{selected}}</blockquote><div class="metrics"><span><b>{{ss.graphemes}}</b> graphemes</span><span><b>{{ss.codepoints}}</b> code points</span><span><b>{{ss.sizes['UTF-8'].bytes.length}} B</b> UTF-8</span><span><b>{{ss.sizes['UTF-8'].bytes.length*8}}</b> bits</span><span><b>{{selectionPercent.toFixed(1)}}%</b> of message UTF-8</span></div><div class="hero-grid selection-hero"><article><small>LARGEST UTF-8 CHARACTER</small><strong class="char">{{ss.largest}}</strong><b>{{ss.largestBytes}} bytes · {{ss.largestBytes*8}} bits</b></article><article><small>SHARE OF MESSAGE</small><strong>{{selectionPercent.toFixed(1)}}%</strong><b>{{ss.sizes['UTF-8'].bytes.length}} of {{total.sizes['UTF-8'].bytes.length}} UTF-8 bytes</b></article></div><div class="rows"><div><b>UTF-8</b><span>{{ss.sizes['UTF-8'].bytes.length}} bytes</span><span>{{ss.sizes['UTF-8'].bytes.length*8}} bits</span></div><div><b>UTF-16</b><span>{{ss.sizes['UTF-16 LE'].bytes.length}} bytes</span><span>{{ss.sizes['UTF-16 LE'].bytes.length*8}} bits</span></div><div><b>UTF-32</b><span>{{ss.sizes['UTF-32 LE'].bytes.length}} bytes</span><span>{{ss.sizes['UTF-32 LE'].bytes.length*8}} bits</span></div></div></div><div v-else class="empty">Highlight text in the input box to analyze only that selection.</div></div>
<div class="panel" v-else-if="active==='Character'"><p class="hint">Hover for a quick look. Click a character to pin it here.</p><div class="charstrip"><span class="char-cell" v-for="(c,i) in graphemes(text)" :key="i"><button @mouseenter="hovered=c" @mouseleave="hovered=''" @focus="hovered=c" @blur="hovered=''" @click="pinned=c" :aria-label="`Inspect ${cpLabel(c)}`">{{c===' '?'␠':c==='\n'?'↵':c}}</button><span v-if="hovered===c" class="char-tip"><b>{{c===' '?'␠':c==='\n'?'↵':c}}</b><small>{{cpLabel(c)}}</small><span>{{size(c,'UTF-8')}} B · {{size(c,'UTF-8')*8}} bits</span></span></span></div><div class="character-detail"><strong>{{pinned}}</strong><div><small>CODE POINT</small><b>{{cpLabel(pinned)}}</b></div><div><small>UTF-8</small><b>{{size(pinned,'UTF-8')}} bytes · {{size(pinned,'UTF-8')*8}} bits</b></div><div class="wide"><small>HEX</small><code>{{hex(pinned)}}</code><small>BINARY</small><code>{{bin(pinned)}}</code></div></div></div>
<div class="panel" v-else-if="active==='File / BOM'">
<div class="control"><div><b>File encoding</b><small>Model the encoded payload independently from the Bytes tab.</small></div><select v-model="fileEncoding"><option v-for="e in encodings" :value="e">{{e}}</option></select></div>
<div class="control"><div><b>Line endings</b><small>Preserve input or model LF, CRLF, or CR without double-counting.</small></div><select v-model="newlineStyle"><option>Preserve</option><option>LF</option><option>CRLF</option><option>CR</option></select></div>
<div class="control"><div><b>Include BOM</b><small>{{bom(fileEncoding).length ? `${bom(fileEncoding).length} byte BOM available for ${fileEncoding}.` : 'No BOM is defined here for this encoding.'}}</small></div><input type="checkbox" v-model="includeBom" :disabled="!bom(fileEncoding).length"></div>
<div class="control"><div><b>Filesystem allocation unit</b><small>Optional estimate for space consumed on disk.</small></div><select v-model="alloc"><option :value="512">512 B</option><option :value="4096">4 KiB</option><option :value="8192">8 KiB</option></select></div>
<div class="rows"><div><b>Text payload</b><span>{{payload}} bytes</span></div><div><b>BOM overhead</b><span>{{bomSize}} bytes</span></div><div class="total"><b>Modeled file size</b><span>{{modeled}} bytes</span></div><div><b>Estimated allocation</b><span>{{allocation}} bytes</span></div></div></div>
<div class="panel" v-else-if="active==='RTF'"><h3>RTF structure & edit comparison</h3><div class="rtf-compare-loaders"><label>Original RTF<input type="file" accept=".rtf,application/rtf,text/rtf" @change="loadRtfSide($event,'original')"><small>{{rtfOriginalName||'Choose the before-edit file'}}</small></label><label>Edited RTF<input type="file" accept=".rtf,application/rtf,text/rtf" @change="loadRtfSide($event,'edited')"><small>{{rtfEditedName||'Choose the after-edit file'}}</small></label></div><div v-if="rtfCompare" class="compare-box"><h4>What changed?</h4><div class="rows"><div><b>Raw file bytes</b><span>{{rtfOriginal!.rawBytes}} → {{rtfEdited!.rawBytes}}</span><span>{{signed(rtfCompare.rawByteDelta)}} B</span></div><div><b>Visible text UTF-8</b><span>{{size(rtfOriginal!.plainText,'UTF-8')}} → {{size(rtfEdited!.plainText,'UTF-8')}} B</span><span>{{signed(rtfCompare.visibleUtf8Delta)}} B</span></div><div><b>Visible graphemes</b><span>{{graphemes(rtfOriginal!.plainText).length}} → {{graphemes(rtfEdited!.plainText).length}}</span><span>{{signed(rtfCompare.visibleGraphemeDelta)}}</span></div><div><b>Control words</b><span>{{rtfOriginal!.controlWords}} → {{rtfEdited!.controlWords}}</span><span>{{signed(rtfCompare.controlWordDelta)}}</span></div><div><b>Unicode / hex escapes</b><span>{{rtfOriginal!.unicodeEscapes}}/{{rtfOriginal!.hexEscapes}} → {{rtfEdited!.unicodeEscapes}}/{{rtfEdited!.hexEscapes}}</span><span>{{signed(rtfCompare.unicodeEscapeDelta)}} / {{signed(rtfCompare.hexEscapeDelta)}}</span></div><div><b>Pictures / objects</b><span>{{rtfOriginal!.pictures}}/{{rtfOriginal!.objects}} → {{rtfEdited!.pictures}}/{{rtfEdited!.objects}}</span><span>{{signed(rtfCompare.pictureDelta)}} / {{signed(rtfCompare.objectDelta)}}</span></div></div><h4>Edited document formatting runs</h4><div v-if="rtfEdited?.runs.length" class="run-list"><div v-for="(run,ri) in rtfEdited.runs" class="run-row" :class="{selected:inspectedRun===ri}" @click="inspectRun(ri)"><code>{{JSON.stringify(run.text)}}</code><span>chars {{run.start}}–{{run.end}}</span><span v-if="run.style.bold">bold</span><span v-if="run.style.italic">italic</span><span v-if="run.style.underline">underline</span><span v-if="run.style.font!==null">{{fontName(rtfEdited!,run.style.font)}} · #{{run.style.font}}</span><span v-if="run.style.fontSizeHalfPoints!==null">{{run.style.fontSizeHalfPoints/2}} pt</span><span v-if="run.style.foregroundColor!==null">{{colorName(rtfEdited!,run.style.foregroundColor)}} · #{{run.style.foregroundColor}}</span><span v-if="run.style.backgroundColor!==null">background {{colorName(rtfEdited!,run.style.backgroundColor)}} · #{{run.style.backgroundColor}}</span><span>{{run.style.alignment}}</span></div></div><div v-if="rtfEdited" class="devtools-grid"><RtfTreeView :source="rtfEditedRaw" :selected-start="treeSelection?.start??null" :selected-end="treeSelection?.end??null" @select="inspectTree"/><div class="computed-pane"><div class="tree-title">APPLIED / COMPUTED</div><template v-if="inspectedRun!==null && rtfEdited.model.runs[inspectedRun]"><strong>{{JSON.stringify(rtfEdited.model.runs[inspectedRun].text)}}</strong><div class="provenance-list"><template v-for="(events,property) in rtfEdited.model.runs[inspectedRun].history" :key="property"><div v-if="events?.length" class="provenance-property"><b>{{property}}</b><div v-for="(event,ei) in events" :key="ei" class="provenance-event" :class="event.kind"><span class="event-kind">{{event.kind}}</span><button class="source-jump" @click="inspectRange(event.sourceStart,event.sourceEnd)"><code>{{event.control}}</code><small>{{event.sourceStart}}–{{event.sourceEnd}}</small></button><span>{{String(event.previousValue)}} → {{String(event.value)}}</span><button v-if="event.reference" class="reference-jump" @click="inspectRange(event.reference.sourceStart,event.reference.sourceEnd)">{{event.reference.kind}} #{{event.reference.index}} · {{event.reference.label}} <small>{{event.reference.sourceStart}}–{{event.reference.sourceEnd}}</small></button></div></div></template></div><div class="computed-label">CASCADE · WINNING SOURCES</div><div class="cascade-list" v-if="rtfEdited.model.runs[inspectedRun].cascade"><button v-for="(source,property) in rtfEdited.model.runs[inspectedRun].cascade" @click="source?.sourceStart!==null&&source?.sourceEnd!==null&&inspectRange(source.sourceStart,source.sourceEnd)" :disabled="source?.sourceStart===null"><b>{{property}}</b><span>{{source?.kind}} · {{source?.label}}</span></button></div><div class="computed-label">COMPUTED VALUES</div><dl><dt>font</dt><dd>{{fontName(rtfEdited,rtfEdited.model.runs[inspectedRun].computedStyle?.font??rtfEdited.model.runs[inspectedRun].style.font)}}</dd><dt>size</dt><dd>{{(rtfEdited.model.runs[inspectedRun].computedStyle?.fontSizeHalfPoints??rtfEdited.model.runs[inspectedRun].style.fontSizeHalfPoints)===null?'default':(rtfEdited.model.runs[inspectedRun].computedStyle?.fontSizeHalfPoints??rtfEdited.model.runs[inspectedRun].style.fontSizeHalfPoints)!/2+' pt'}}</dd><dt>weight</dt><dd>{{(rtfEdited.model.runs[inspectedRun].computedStyle?.bold??rtfEdited.model.runs[inspectedRun].style.bold)?'bold':'normal'}}</dd><dt>style</dt><dd>{{(rtfEdited.model.runs[inspectedRun].computedStyle?.italic??rtfEdited.model.runs[inspectedRun].style.italic)?'italic':'normal'}}</dd><dt>underline</dt><dd>{{(rtfEdited.model.runs[inspectedRun].computedStyle?.underline??rtfEdited.model.runs[inspectedRun].style.underline)?'yes':'no'}}</dd><dt>color</dt><dd>{{colorName(rtfEdited,(rtfEdited.model.runs[inspectedRun].computedStyle??rtfEdited.model.runs[inspectedRun].style).foregroundColor)}}</dd><dt>background</dt><dd>{{colorName(rtfEdited,(rtfEdited.model.runs[inspectedRun].computedStyle??rtfEdited.model.runs[inspectedRun].style).backgroundColor)}}</dd><dt>alignment</dt><dd>{{(rtfEdited.model.runs[inspectedRun].computedStyle??rtfEdited.model.runs[inspectedRun].style).alignment}}</dd><dt>left indent</dt><dd>{{(rtfEdited.model.runs[inspectedRun].computedStyle??rtfEdited.model.runs[inspectedRun].style).leftIndentTwips}} twips</dd><dt>right indent</dt><dd>{{(rtfEdited.model.runs[inspectedRun].computedStyle??rtfEdited.model.runs[inspectedRun].style).rightIndentTwips}} twips</dd><dt>first line</dt><dd>{{(rtfEdited.model.runs[inspectedRun].computedStyle??rtfEdited.model.runs[inspectedRun].style).firstLineIndentTwips}} twips</dd><dt>space before</dt><dd>{{(rtfEdited.model.runs[inspectedRun].computedStyle??rtfEdited.model.runs[inspectedRun].style).spaceBeforeTwips}} twips</dd><dt>space after</dt><dd>{{(rtfEdited.model.runs[inspectedRun].computedStyle??rtfEdited.model.runs[inspectedRun].style).spaceAfterTwips}} twips</dd><dt>line spacing</dt><dd>{{(rtfEdited.model.runs[inspectedRun].computedStyle??rtfEdited.model.runs[inspectedRun].style).lineSpacingTwips===null?'default':(rtfEdited.model.runs[inspectedRun].computedStyle??rtfEdited.model.runs[inspectedRun].style).lineSpacingTwips+' twips'}}</dd><dt>tab stops</dt><dd>{{(rtfEdited.model.runs[inspectedRun].computedStyle??rtfEdited.model.runs[inspectedRun].style).tabStopsTwips.length?(rtfEdited.model.runs[inspectedRun].computedStyle??rtfEdited.model.runs[inspectedRun].style).tabStopsTwips.join(', ')+' twips':'default'}}</dd><dt>paragraph style</dt><dd v-if="rtfEdited.model.runs[inspectedRun].paragraphStyleResolution" class="style-chain"><button v-for="style in rtfEdited.model.runs[inspectedRun].paragraphStyleResolution!.chain" @click="inspectRange(style.sourceStart,style.sourceEnd)" :title="'Open stylesheet source for '+style.name">{{style.name}} · \\s{{style.index}}</button><span v-if="rtfEdited.model.runs[inspectedRun].paragraphStyleResolution!.missingParent!==null">missing parent \\s{{rtfEdited.model.runs[inspectedRun].paragraphStyleResolution!.missingParent}}</span><span v-if="rtfEdited.model.runs[inspectedRun].paragraphStyleResolution!.cycle">inheritance cycle</span></dd><dd v-else>none</dd><dt>character style</dt><dd v-if="rtfEdited.model.runs[inspectedRun].characterStyleResolution" class="style-chain"><button v-for="style in rtfEdited.model.runs[inspectedRun].characterStyleResolution!.chain" @click="inspectRange(style.sourceStart,style.sourceEnd)" :title="'Open stylesheet source for '+style.name">{{style.name}} · \\cs{{style.index}}</button><span v-if="rtfEdited.model.runs[inspectedRun].characterStyleResolution!.missingParent!==null">missing parent \\cs{{rtfEdited.model.runs[inspectedRun].characterStyleResolution!.missingParent}}</span><span v-if="rtfEdited.model.runs[inspectedRun].characterStyleResolution!.cycle">inheritance cycle</span></dd><dd v-else>none</dd><dt>list</dt><dd v-if="rtfEdited.model.runs[inspectedRun].listResolution" class="list-chain"><button @click="inspectRange(rtfEdited.model.runs[inspectedRun].listResolution!.override.sourceStart,rtfEdited.model.runs[inspectedRun].listResolution!.override.sourceEnd)">\\ls{{rtfEdited.model.runs[inspectedRun].listResolution!.ls}} override</button><span>→</span><button @click="inspectRange(rtfEdited.model.runs[inspectedRun].listResolution!.list.sourceStart,rtfEdited.model.runs[inspectedRun].listResolution!.list.sourceEnd)">list {{rtfEdited.model.runs[inspectedRun].listResolution!.list.listId}}</button><span>→</span><button v-if="rtfEdited.model.runs[inspectedRun].listResolution!.levelDefinition" @click="inspectRange(rtfEdited.model.runs[inspectedRun].listResolution!.levelDefinition!.sourceStart,rtfEdited.model.runs[inspectedRun].listResolution!.levelDefinition!.sourceEnd)">level {{rtfEdited.model.runs[inspectedRun].listResolution!.level}}</button><span v-if="rtfEdited.model.runs[inspectedRun].listResolution!.levelDefinition" class="list-explain">{{rtfEdited.model.runs[inspectedRun].listResolution!.levelDefinition!.numberFormatName}} · starts at {{rtfEdited.model.runs[inspectedRun].listResolution!.levelDefinition!.startAt??'default'}}</span></dd><dd v-else>{{rtfEdited.model.runs[inspectedRun].style.listOverride===null?'none':'unresolved \\ls'+rtfEdited.model.runs[inspectedRun].style.listOverride+' level '+(rtfEdited.model.runs[inspectedRun].style.listLevel??0)}}</dd><dt>source</dt><dd>{{rtfEdited.model.runs[inspectedRun].sourceStart}}–{{rtfEdited.model.runs[inspectedRun].sourceEnd}}</dd></dl></template><p v-else class="hint">Select a rendered run, source token, or tree node.</p></div></div><div v-if="inspectedRun!==null && rtfEdited?.model.runs[inspectedRun]" class="source-inspector"><div class="source-pane"><small>RTF SOURCE · {{sourceBytes(rtfEdited.model.runs[inspectedRun])}} MAPPED BYTES</small><pre class="source-code"><button v-for="(token,ti) in sourceTokens" :key="ti" class="source-token" :class="[token.kind,{active:token.run===inspectedRun,focused:treeSelection && token.start < treeSelection.end && token.end > treeSelection.start}]" @click="inspectSourceToken(token)" :title="token.run===null?`Unmapped source ${token.start}–${token.end}`:`Mapped to rendered run ${token.run+1}`">{{token.text}}</button></pre></div><aside><small>INSPECTED RUN</small><strong>{{JSON.stringify(rtfEdited.model.runs[inspectedRun].text)}}</strong><p>Rendered chars {{rtfEdited.model.runs[inspectedRun].start}}–{{rtfEdited.model.runs[inspectedRun].end}} · source {{rtfEdited.model.runs[inspectedRun].sourceStart}}–{{rtfEdited.model.runs[inspectedRun].sourceEnd}}</p><div class="control-list"><div v-for="token in rtfEdited.model.runs[inspectedRun].sourceTokens.filter(t=>t.type==='control-word'||t.type==='control-symbol')"><code>{{token.raw.trim()}}</code><span>{{token.type}}</span><small>source {{token.start}}–{{token.end}}</small></div></div></aside></div><p class="hint">Character ranges are positions in the parser's extracted text. Font names and RGB values are resolved from the RTF font/color tables; the original table indexes remain visible for verification.</p><h4>Formatting controls detected</h4><div v-if="rtfCompare.formattingChanges.length" class="format-chips"><span v-for="change in rtfCompare.formattingChanges">{{change}}</span></div><p v-else class="hint">No change in the common formatting controls currently decoded.</p><h4>Learn from this edit</h4><div class="lessons"><p v-for="lesson in rtfCompare.lessons">{{lesson}}</p></div></div><p class="hint">RTF file bytes and formatting syntax are reported separately from extracted visible text.</p><div v-if="rtfStats"><div class="metrics"><span><b>{{openedBytes}}</b> raw file bytes</span><span><b>{{rtfStats.controlWords}}</b> control words</span><span><b>{{rtfStats.groups}}</b> groups</span><span><b>{{rtfStats.unicodeEscapes}}</b> Unicode escapes</span><span><b>{{rtfStats.hexEscapes}}</b> hex escapes</span></div><div class="rows"><div><b>Opened file</b><span>{{openedFile}}</span><span>{{rtfStats.rawBytes}} B</span></div><div><b>Extracted visible text</b><span>{{size(rtfStats.plainText,'UTF-8')}} B UTF-8</span><span>{{graphemes(rtfStats.plainText).length}} graphemes</span></div><div><b>Font table source</b><span>{{rtfStats.fontTableChars}} source chars</span><span></span></div><div><b>Color table source</b><span>{{rtfStats.colorTableChars}} source chars</span><span></span></div><div><b>Embedded pictures</b><span>{{rtfStats.pictures}}</span><span></span></div><div><b>Embedded objects</b><span>{{rtfStats.objects}}</span><span></span></div></div></div><div v-else class="empty">Open an .rtf file to inspect its raw size, formatting/control overhead, escapes, embedded content markers, and extracted text.</div></div>
<div class="panel converter" v-else-if="active==='Converter'"><h3>Unicode & entity converter</h3><p class="hint">Convert actual text into source representations, or decode numeric HTML entities and JavaScript/Unicode escapes back to characters.</p><textarea v-model="convertInput" spellcheck="false"></textarea><div class="converter-tools"><select v-model="convertMode"><option>Unicode code points</option><option>JavaScript escapes</option><option>HTML decimal</option><option>HTML hexadecimal</option><option>UTF-8 hex</option></select><button @click="decodeIntoInput">Decode input → text</button></div><small>OUTPUT</small><code class="bitbox">{{converted}}</code><div class="metrics"><span><b>{{size(convertInput,'UTF-8')}}</b> input UTF-8 bytes</span><span><b>{{size(converted,'UTF-8')}}</b> representation UTF-8 bytes</span></div></div>
<div class="panel" v-else><h3>UTF-8 bit stream</h3><code class="bitbox">{{bin(text)}}</code></div>
</section></main></div>
</template>
